/* College-aware detail views and automatic AI fallback search. */
(() => {
  'use strict';
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const clean = v => String(v || '').replace(/\s+/g, ' ').trim();
  const displayValue = v => { const value = clean(v); return /^(n\/?a|na|없음|미상|unknown|null|undefined|-+)$/i.test(value) ? '' : value; };
  const safeUrl = v => { try { const u = new URL(String(v || '')); return /^https?:$/.test(u.protocol) ? u.href : ''; } catch (_) { return ''; } };
  const allUnits = () => [...(window.RESEARCH_UNITS || []), ...(window.RESEARCH_UNIT_SUPPLEMENTS || [])];
  const enrichment = x => (window.PRECOMPUTED_ENRICHMENT || {})[x.id] || {};
  const activity = x => (window.RESEARCH_ACTIVITY || {})[x.id] || {};
  const fallbackActivityHtml = window.activityHtml;
  function profile(x){const college=clean(x.college);if(/음악대학/.test(college))return'music';if(/미술대학/.test(college))return'fine_arts';if(/인문대학/.test(college))return'humanities';return'scholarly';}
  function verifiedItems(items,empty,withSummary=false,showPendingSummary=false){const list=(Array.isArray(items)?items:[]).filter(item=>item&&clean(item.title||item.name));if(!list.length)return'<p class="activity-empty">'+esc(empty)+'</p>';return'<ul class="activity-list compact-list">'+list.slice(0,3).map(item=>{const label=displayValue(item.title||item.name),note=displayValue(item.venue||item.organization||item.role||item.description),date=displayValue(item.date||item.year),summary=withSummary?displayValue(item.summary):'',link=safeUrl(item.url);return'<li><div>'+(link?'<a target="_blank" rel="noreferrer" href="'+esc(link)+'">'+esc(label)+'</a>':'<span>'+esc(label)+'</span>')+(note?'<small>'+esc(note)+'</small>':'')+(summary?'<p class="item-summary">'+esc(summary)+'</p>':(showPendingSummary?'<p class="item-summary pending-summary">논문 요약 수집 중</p>':''))+'</div>'+(date?'<span>'+esc(date)+'</span>':'')+'</li>';}).join('')+'</ul>';}
  function sourceLink(){return'';}
  function posterCard(e,a={}){const verified=String(e.poster_status||a.posterStatus||'').toLowerCase()==='verified',image=verified?safeUrl(e.poster_image_url):'',source=verified?safeUrl(e.poster_source_url):'';if(!image)return'';return'<div class="activity-grid poster-grid"><article class="activity-card poster"><h4>연구 포스터</h4><a class="poster-found" target="_blank" rel="noreferrer" href="'+esc(source||image)+'"><img src="'+esc(image)+'" alt="'+esc(e.poster_title||'연구 포스터')+'"><strong>'+esc(e.poster_title||'포스터 원문 보기')+'</strong></a></article></div>';}
  function creativeActivityHtml(x,type){const e=enrichment(x),a=activity(x),isMusic=type==='music',title=isMusic?'음악 활동':'예술 활동',subtitle=isMusic?'공식 출처에서 확인된 공연·작품·교육 활동을 핵심 항목만 보여줍니다.':'공식 교수 페이지에서 확인된 최신 개인전·단체전을 최대 3건씩 보여줍니다.';const cards=isMusic?[["최근 공연·발표",verifiedItems(e.recent_performances,'최근 공연·발표 실적을 아직 확인하지 못했습니다.',true)],["작품·창작 실적",verifiedItems(e.creative_works,'확인된 작품·창작 실적이 아직 없습니다.',true)],["전공·교육 활동",'<p class="activity-ai-text">'+esc(clean(e.education_summary||e.research_summary||x.fields)||'공식 소개의 전공·교육 활동 설명을 수집 중입니다.')+'</p>']]:[["최근 개인전",verifiedItems(e.recent_solo_exhibitions,'공식 출처에서 확인된 개인전이 아직 없습니다.',true)],["최근 단체전",verifiedItems(e.recent_group_exhibitions,'공식 출처에서 확인된 단체전이 아직 없습니다.',true)],["전공·교육 활동",'<p class="activity-ai-text">'+esc(clean(e.education_summary||e.research_summary||x.fields)||'공식 소개의 전공·교육 활동 설명을 수집 중입니다.')+'</p>']];return'<section class="activity-wrap discipline-activity '+type+'"><div class="activity-title"><div><h3>'+title+'</h3><p>'+subtitle+'</p></div></div><div class="activity-grid">'+cards.map(([heading,body])=>'<article class="activity-card"><h4>'+heading+'</h4>'+body+'</article>').join('')+'</div>'+posterCard(e,a)+sourceLink(e)+'</section>';}
  function humanitiesActivityHtml(x){const e=enrichment(x),a=activity(x),papers=Array.isArray(e.recent_papers)&&e.recent_papers.length?e.recent_papers:(a.papers||[]);return'<section class="activity-wrap discipline-activity humanities"><div class="activity-title"><div><h3>학술 활동</h3><p>공식 출처에서 확인된 핵심 학술 활동만, 항목별 최대 3건으로 보여줍니다.</p></div></div><div class="activity-grid"><article class="activity-card"><h4>최근 논문</h4>'+verifiedItems(papers,'확인된 논문 목록이 아직 없습니다.',true)+'</article><article class="activity-card"><h4>저서·편저</h4>'+verifiedItems(e.books,'확인된 저서·편저 목록이 아직 없습니다.',true)+'</article><article class="activity-card"><h4>연구과제·학술발표</h4>'+verifiedItems([...(e.research_projects||[]),...(e.conference_presentations||[])],'확인된 연구과제·학술발표가 아직 없습니다.',true)+'</article></div>'+posterCard(e,a)+sourceLink(e)+'</section>';}
  function paperStatsHtml(e){const total=Number.isInteger(e.recent_year_paper_count)?e.recent_year_paper_count:null,groups=(Array.isArray(e.recent_year_papers_by_venue)?e.recent_year_papers_by_venue:[]).filter(item=>item&&clean(item.venue)&&Number.isInteger(item.count)&&item.count>0).slice(0,6);if(total===null&&!groups.length)return'<p class="paper-stats pending-summary">최근 1년 논문 수·게재처별 통계 수집 중</p>';return'<div class="paper-stats">'+(total!==null?'<p>최근 1년 논문 <strong>총 '+esc(total)+'편</strong></p>':'')+(groups.length?'<p class="paper-venues">게재처별: '+groups.map(item=>esc(clean(item.venue)+' '+item.count+'편')).join(' · ')+'</p>':'')+'</div>';}
  function academicActivityHtml(x){const e=enrichment(x),a=activity(x),papers=Array.isArray(e.recent_papers)&&e.recent_papers.length?e.recent_papers:(a.papers||[]),people=Array.isArray(e.current_members)?e.current_members:[],recruitmentUrl=safeUrl(e.recruitment_source_url)||safeUrl((e.verified_recruitment_pages||[])[0]?.url),groups=people.reduce((acc,person)=>{const role=clean(person.role),key=/박사/.test(role)?'박사과정':/석사/.test(role)?'석사과정':/학부/.test(role)?'학부연구생':/교수|연구원|postdoc/i.test(role)?'교수·연구원':'기타';acc[key]=(acc[key]||0)+1;return acc;},{}),memberText=Object.entries(groups).map(([name,count])=>name+' '+count+'명').join(' · ');return'<section class="activity-wrap discipline-activity scholarly"><div class="activity-title"><div><h3>연구실 핵심 정보</h3></div></div><div class="activity-grid"><article class="activity-card"><h4>최신 논문 3편</h4>'+paperStatsHtml(e)+verifiedItems(papers,'확인된 최근 논문이 아직 없습니다.',true,true)+'</article><article class="activity-card"><h4>모집 현황</h4><p class="activity-ai-text">'+esc(clean(e.recruitment_summary)||'현재 모집으로 검증된 공식 안내가 없습니다.')+'</p>'+(recruitmentUrl?'<a class="small-link" target="_blank" rel="noreferrer" href="'+esc(recruitmentUrl)+'">모집 공식 안내</a>':'')+'</article><article class="activity-card"><h4>구성</h4><p class="activity-ai-text">'+esc(memberText||'확인된 구성원 현황이 아직 없습니다.')+'</p></article></div>'+posterCard(e,a)+sourceLink(e)+'</section>';}
  window.activityHtml=function(x){const kind=profile(x);if(kind==='music'||kind==='fine_arts')return creativeActivityHtml(x,kind);if(kind==='humanities')return humanitiesActivityHtml(x);return academicActivityHtml(x);};
})();
